// PASO 1 - Contrato de entrada. Corre ANTES del modelo: cuesta 0 tokens.

const RE_EMAIL = /^[^@\s]+@[^@\s]+\.[^@\s]+$/;
const salida = [];

for (const item of $input.all()) {
  const body = item.json.body ?? item.json;
  const errores = [];

  const email = String( $input.first().json.query.email?? '').trim().toLowerCase();
  const mensaje = String( $input.first().json.query.mensaje?? '').trim();

  if (!RE_EMAIL.test(email)) { errores.push('email ausente o con formato invalido'); }
  if (mensaje.length < 5) { errores.push('mensaje ausente o demasiado corto (minimo 5 caracteres)'); }

  const contacto = {
    email: email,
    nombreAlumno: String($input.first().json.query.nombreAlumno?? '').trim() || null,
    apellidoFamilia: String( $input.first().json.query.nombreFamilia?? '').trim() || null,
    colegio:String( $input.first().json.query.colegio?? '').trim() || null,
    mensaje: mensaje
  };

  salida.push({ json: {
    valido: errores.length === 0,
    errores: errores,
    trace_id: 'Contacto-' + $execution.id,
    recibido_en: new Date().toISOString(),
    contacto: contacto
  }});
}

return salida;

// ================= GUARDRAIL DE SEGURIDAD =================
// Corre ANTES del modelo: cuesta 0 tokens y no se puede convencer con palabras.
// Hace tres cosas, siempre en este orden:
//   1) datos sensibles  → los graves BLOQUEAN, los medios se TACHAN y el mensaje sigue
//   2) prompt injection → cada patrón detectado suma puntos; al llegar a 3, bloquea
//   3) veredicto        → estado OK o BLOQUEADO (INVALIDO ya viene decidido de antes)

// ---------- PARTE 1 · LAS REGLAS ----------
// Toda la política de seguridad vive en estas tres tablas. Para cambiar qué
// se detecta, se edita una tabla — la lógica de abajo no se toca nunca.

// Severidad ALTA: si aparece uno de estos, el mensaje entero se rechaza (HTTP 422).
// Estos datos no tienen por qué existir en este canal.
const BLOQUEAN = [
  { tipo: 'TARJETA_CREDITO', que: 'número de tarjeta que además pasa Luhn', extra: esTarjetaReal,
    re: /\b(?:\d[ .-]?){12,18}\d\b/g },
  { tipo: 'CVV', que: 'código de seguridad de tarjeta',
    re: /\b(?:cvv|cvc|cod(?:igo)?\.?\s*(?:de\s*)?seguridad)\b\D{0,10}\d{3,4}\b/gi },
  { tipo: 'API_KEY', que: 'llave de API estilo OpenAI',
    re: /\bsk-[A-Za-z0-9_-]{16,}\b/g },
  { tipo: 'TOKEN_BEARER', que: 'token de autorización',
    re: /\bBearer\s+[A-Za-z0-9_.-]{20,}/gi },
  { tipo: 'PASSWORD', que: 'contraseña en texto plano',
    re: /\b(?:password|contrase[nñ]a|clave|pwd|pass)\b\s*[:=]\s*\S{4,}/gi },
];

// Severidad MEDIA: se tachan del texto y el lead sigue su camino.
// Un CUIT en un pedido de factura es legítimo — pero no tiene por qué viajar al modelo.
const SE_REDACTAN = [
  { tipo: 'CUIT_CUIL', que: 'identificador fiscal argentino', re: /\b\d{2}-?\d{8}-?\d\b/g },
  { tipo: 'IBAN',      que: 'cuenta bancaria internacional',  re: /\b[A-Z]{2}\d{2}[A-Z0-9]{11,30}\b/g },
  { tipo: 'CBU',       que: 'cuenta bancaria argentina',      re: /\b\d{22}\b/g },
  { tipo: 'DNI',       que: 'documento de identidad',         re: /\bdni\b\D{0,6}\d{7,8}\b/gi },
];

// Prompt injection: nadie bloquea solo — cada patrón suma su peso y decide la suma.
// Peso 3 = casi siempre hostil. Peso 2 = sospechoso, pero puede aparecer en una
// pregunta honesta ("¿el sistema actúa como un CRM?"), por eso no alcanza solo.
const UMBRAL = 3;
const INYECCION = [
  { peso: 3, tipo: 'OVERRIDE_INSTRUCCIONES', re: /\b(ignor[aáe]\w*|olvid[aá]\w*|descart[aá]\w*|disregard|forget)\b[\s\S]{0,40}\b(instruccion\w*|instruction\w*|regla\w*|rule\w*|prompt|anterior\w*|previous|above)\b/i },
  { peso: 3, tipo: 'EXTRACCION_PROMPT',      re: /\b(system\s*prompt|prompt\s*del\s*sistema|instruccion\w*\s*del\s*sistema|tus\s*instruccion\w*|your\s*instructions)\b/i },
  { peso: 3, tipo: 'JAILBREAK',              re: /\b(DAN\s*mode|developer\s*mode|modo\s*desarrollador|jailbreak|sin\s*restriccion\w*|no\s*filters|unfiltered)\b/i },
  { peso: 3, tipo: 'MANIPULACION_TAXONOMIA', re: /\b(clasific[aá]\w*|categoriz[aá]\w*|marc[aá]\w*|etiquet[aá]\w*)\b[\s\S]{0,40}\b(NUEVO_LEAD|SPAM|ESCALAMIENTO|CONSULTA_SOPORTE)\b/i },
  { peso: 2, tipo: 'CAMBIO_DE_ROL',          re: /\b(actu[aá]\s*como|comport[aá]te\s*como|act\s*as\s*(a|an)?|you\s*are\s*now|a\s*partir\s*de\s*ahora\s*(sos|eres)|pretend\s*(to\s*be|you)|roleplay)\b/i },
  { peso: 2, tipo: 'DELIMITADORES_FALSOS',   re: /(<\|im_(start|end)\|>|\[\/?INST\]|<<SYS>>|###\s*(system|instruction)|^\s*(system|assistant)\s*:)/im },
  { peso: 2, tipo: 'FORZADO_DE_SALIDA',      re: /\b(respond[eé]\w*|devolv[eé]\w*|output|return|contest[aá]\w*)\b[\s\S]{0,30}\b(exactamente|solamente|solo|only|exactly|el\s*siguiente\s*json|this\s*json)\b/i },
  { peso: 2, tipo: 'MANIPULACION_CONFIANZA', re: /\bconfianza\b[\s\S]{0,20}\b(1|1\.0|100|uno|maxima)\b/i },
];

// ---------- PARTE 2 · EL MOTOR ----------
// Tres funciones cortas. No hay más lógica que esta.

// Luhn: la suma de control que toda tarjeta real cumple. Sin esto, cualquier
// número largo (un teléfono, un ID de contrato) sería un falso positivo.
function luhn(digitos) {
  if (digitos.length < 13 || digitos.length > 19) return false;
  let suma = 0;
  for (let i = 0; i < digitos.length; i++) {
    let d = Number(digitos[digitos.length - 1 - i]);   // recorremos desde el final
    if (Number.isNaN(d)) return false;
    if (i % 2 === 1) { d *= 2; if (d > 9) d -= 9; }    // duplicar uno de cada dos
    suma += d;
  }
  return suma % 10 === 0;                              // si cierra en múltiplo de 10, es tarjeta
}

// El chequeo extra de la regla TARJETA_CREDITO: dígitos solos, y que Luhn cierre.
function esTarjetaReal(match) {
  return luhn(match.replace(/\D/g, ''));
}

// Pasa el texto por una tabla de reglas: cada match se reemplaza por su marca
// y queda anotado como hallazgo. Sirve igual para bloquear que para redactar.
function aplicar(reglas, texto, marca, severidad) {
  const hallazgos = [];
  for (const regla of reglas) {
    let hubo = false;
    texto = texto.replace(regla.re, (m) => {
      if (regla.extra && !regla.extra(m)) return m;    // ej.: número largo que NO es tarjeta, se deja
      hubo = true;
      return '[' + marca + ':' + regla.tipo + ']';
    });
    if (hubo) hallazgos.push({ tipo: regla.tipo, severidad: severidad, detalle: regla.que });
  }
  return { hallazgos: hallazgos, texto: texto };
}

// Datos sensibles = las dos tablas, en orden: primero lo grave, después lo redactable.
function analizarSensibles(texto) {
  const altas = aplicar(BLOQUEAN, texto, 'BLOQUEADO', 'alta');
  const medias = aplicar(SE_REDACTAN, altas.texto, 'REDACTADO', 'media');
  return { hallazgos: altas.hallazgos.concat(medias.hallazgos), texto_limpio: medias.texto };
}

// Injection = qué patrones aparecen y cuánto suman.
function analizarInjection(texto) {
  const detectados = INYECCION.filter((p) => p.re.test(texto));
  const puntaje = detectados.reduce((suma, p) => suma + p.peso, 0);
  return { puntaje: puntaje, detectados: detectados, bloquea: puntaje >= UMBRAL };
}

// ---------- PARTE 3 · EL VEREDICTO ----------
// Por cada mensaje que llega: analizar, decidir el estado y armar el informe.

const salida = [];

for (const item of $input.all()) {
  const e = item.json;

  // Si el contrato ya falló en el nodo anterior, no hay nada que analizar acá.
  if (!e.valido) {
    salida.push({ json: { ...e, estado: 'INVALIDO', seguridad: null } });
    continue;
  }

  const original = e.contacto.mensaje;
  const sens = analizarSensibles(original);
  const inj = analizarInjection(original);

  // Bloquea si hubo un hallazgo grave O si la suma de injection llegó al umbral.
  const graves = sens.hallazgos.filter((h) => h.severidad === 'alta');
  const bloquea = graves.length > 0 || inj.bloquea;

  // Los motivos dicen el TIPO de hallazgo — nunca el valor detectado.
  const motivos = graves.map((h) => 'dato sensible ' + h.tipo + ': ' + h.detalle);
  if (inj.bloquea) {
    motivos.push('prompt injection: puntaje ' + inj.puntaje + ' alcanza el umbral ' + UMBRAL);
  }

  salida.push({ json: { ...e,
    estado: bloquea ? 'BLOQUEADO' : 'OK',
    contacto: { ...e.contacto, mensaje: sens.texto_limpio },   // el modelo NUNCA ve el texto original
    seguridad: {
      bloqueado: bloquea,
      motivos: motivos,
      datos_sensibles: sens.hallazgos,
      redacciones: sens.hallazgos.filter((h) => h.severidad === 'media').map((h) => h.tipo),
      texto_modificado: sens.texto_limpio !== original,
      injection: { puntaje: inj.puntaje, umbral: UMBRAL, patrones: inj.detectados.map((d) => d.tipo) }
    }
  }});
}

return salida;

