// PASO 3 - Guardrail semantico: el modelo propone, el codigo dispone.

const UMBRAL_CONFIANZA = 0.5;
const INTENCIONES_VALIDAS = ['NUEVO_CONTACTO', 'CONSULTA_MENU', "CONSULTA_SALDO", 'SPAM', 'ESCALAMIENTO'];

const entrada = $('Guardrail de Seguridad').first().json;
const salida = [];

for (const item of $input.all()) {
  const c = item.json.output ?? item.json;

  const intencion = String(c.intencion ?? '').toUpperCase();
  const confianza = Number(c.confianza ?? 0);

  let ruta = intencion;
  let motivo_guardrail = null;

  if (!INTENCIONES_VALIDAS.includes(intencion)) {
    ruta = 'ESCALAMIENTO';
    motivo_guardrail = 'el modelo devolvio una intencion fuera de la taxonomia: "' + intencion + '"';
  } else if (!Number.isFinite(confianza) || confianza < UMBRAL_CONFIANZA) {
    ruta = 'ESCALAMIENTO';
    motivo_guardrail = 'confianza ' + confianza + ' por debajo del umbral ' + UMBRAL_CONFIANZA;
  }

  salida.push({ json: {
    trace_id: entrada.trace_id,
    contacto: entrada.contacto,
    seguridad: entrada.seguridad,
    clasificacion: {
      intencion: intencion,
      confianza: confianza,
      prioridad: c.prioridad ?? 'media',
      motivo: c.motivo ?? null,
      senales: c.senales ?? []
    },
    ruta: ruta,
    guardrail_aplicado: motivo_guardrail !== null,
    motivo_guardrail: motivo_guardrail
  }});
}

return salida;

