// Junta lo que sabe el Manager con lo que devolvio el Worker de scoring
// y arma el payload minimo que necesita el Worker de registro.
// Esto es el "Set antes de delegar": el Worker 2 no ve el payload crudo del webhook.

const ctx = $('Guardrail de confianza').first().json;
const califico = $input.first().json;

return [{ json: {
  trace_id: ctx.trace_id,
  contacto: ctx.contacto,
  clasificacion: ctx.clasificacion,
  scoring: califico.status === 'ok' ? califico.data : null,
  error_calificacion: califico.status === 'error' ? califico.error : null
}}];

// PASO 4 - Contrato de salida unico. Convergen las 4 rutas.

const ctx = $('Guardrail de confianza').first().json;
const entrada = $input.first().json;

// Solo la rama NUEVO_LEAD pasa por los Workers. Se reconoce por el contrato { status, data }.
const vieneDeWorker = entrada !== null && typeof entrada === 'object' && 'status' in entrada && 'data' in entrada;
const registro = vieneDeWorker && entrada.status === 'ok' ? entrada.data : null;
const errorWorker = vieneDeWorker && entrada.status === 'error' ? entrada.error : null;

// El scoring lo dejo el Worker 1; se recupera desde el nodo que preparo el registro.
let scoring = null;
let errorCalificacion = null;
if (vieneDeWorker) {
  const prep = $('Preparar Registro Nuevo Contacto').first().json;
  scoring = prep.scoring;
  errorCalificacion = prep.error_calificacion;
}

const ACCIONES = {
  NUEVO_CONTACTO: { accion: 'calificado_y_registrado', mensaje: 'Contacto calificado, registrado y asignado al equipo comercial.' },
  CONSULTA_MENU: { accion: 'derivado_a_menus', mensaje: 'No es una oportunidad de venta: el caso se deriva a la consultade menues.' },
  CONSULTA_SALDO: { accion: 'derivado_a_facturacion', mensaje: 'El caso se deriva a la consulta de saldos adeudados.' },
  SPAM: { accion: 'descartado', mensaje: 'Mensaje descartado por el filtro de spam. No se creo ningun registro.' },
  ESCALAMIENTO: { accion: 'escalado_a_humano', mensaje: 'Escalado a revision humana. Un responsable comercial va a leer el caso.' }
};

const plan = ACCIONES[ctx.ruta] ?? ACCIONES.ESCALAMIENTO;
const hayError = errorWorker !== null || errorCalificacion !== null;

let mensaje = plan.mensaje;
if (registro && registro.duplicado) {
  mensaje = 'El contacto ya estaba registrado: no se duplico la fila, se actualizo el ultimo contacto (contacto numero ' + registro.veces_visto + ').';
}
if (hayError) {
  mensaje = 'Un Worker no pudo completar su tarea, asi que el caso queda para revision humana.';
}

const respuesta = {
  status: hayError ? 'error' : 'ok',
  trace_id: ctx.trace_id,
  ruta: hayError ? 'ESCALAMIENTO' : ctx.ruta,
  accion: hayError ? 'escalado_a_humano' : (registro && registro.duplicado ? 'actualizado_sin_duplicar' : plan.accion),
  mensaje: mensaje,
  clasificacion: ctx.clasificacion,
  seguridad: {
    bloqueado: false,
    redacciones: ctx.seguridad ? ctx.seguridad.redacciones : [],
    injection_puntaje: ctx.seguridad ? ctx.seguridad.injection.puntaje : 0
  },
  guardrail: { aplicado: ctx.guardrail_aplicado, motivo: ctx.motivo_guardrail },
  scoring: scoring,
  registro: registro,
  error: errorWorker ?? errorCalificacion,
  contacto: { email: ctx.contacto.email, familia: ctx.contacto.apellidoFamilia }
};

return [{ json: { http_status: hayError ? 502 : 200, respuesta: respuesta } }];

// PASO 5 - Trazabilidad. Corre DESPUES de "Responder": el cliente ya tiene
// su respuesta y el log no le agrega latencia a nadie.
// Deja UNA fila por ejecucion, pase lo que pase: 200, 400, 422 o 502.
// La tabla de leads guarda el QUE (el dato de negocio);
// esta guarda el COMO (que camino tomo cada request y cuanto tardo).

const r = $json.respuesta;
const norm = $('Normalizar Datos de la Entrada').first().json;
const ahora = new Date();

// Que Workers actuaron se deduce de lo que dejo cada uno en la respuesta.
const workers = [];
if (r.scoring) workers.push('calificar');
if (r.registro) workers.push('registrar');

// Resumen de seguridad: se loguean TIPOS de hallazgo, nunca los valores.
const seg = r.seguridad ?? {};
const partes = [];
if (seg.motivos && seg.motivos.length) partes.push(seg.motivos.join(' | '));
if (seg.redacciones && seg.redacciones.length) partes.push('redactado: ' + seg.redacciones.join(','));
const inj = seg.injection ? seg.injection.puntaje : (seg.injection_puntaje ?? 0);
if (inj && !partes.some((p) => p.includes('injection'))) partes.push('injection puntaje ' + inj);

// El error puede venir de un Worker (502) o del contrato de entrada (400).
let error = '';
if (r.error) error = typeof r.error === 'string' ? r.error : JSON.stringify(r.error);
if (r.errores && r.errores.length) error = r.errores.join(' | ');

return [{ json: { fila: {
  trace_id: String(r.trace_id ?? ''),
  recibido_en: String(norm.recibido_en ?? ''),
  duracion_ms: ahora.getTime() - new Date(norm.recibido_en).getTime(),
  http_status: Number($json.http_status ?? 0),
  ruta: String(r.ruta ?? ''),
  accion: String(r.accion ?? ''),
  email: String((r.lead && r.contacto.email) || (norm.contacto && norm.contacto.email) || ''),
  uso_llm: Boolean(r.clasificacion),
  intencion: r.clasificacion ? String(r.clasificacion.intencion) : '',
  confianza: r.clasificacion ? Number(r.clasificacion.confianza) : 0,
  workers: workers.join(','),
  score: r.scoring ? Number(r.scoring.score) : 0,
  bloqueado: Boolean(seg.bloqueado),
  detalle_seguridad: partes.join(' · '),
  error: error
} } }];

// Payload que no cumple el contrato. Se responde 400 SIN gastar un token.

const e = $input.first().json;

return [{ json: {
  http_status: 400,
  respuesta: {
    status: 'error',
    trace_id: e.trace_id,
    ruta: 'RECHAZADO_FALTAN_DATOS',
    accion: 'rechazado',
    mensaje: 'El payload no cumple el contrato minimo de entrada. No se llamo al modelo ni a ningun Worker.',
    errores: e.errores,
    contrato_esperado: { email: 'string (obligatorio)', mensaje: 'string, minimo 5 caracteres (obligatorio)' }
  }
}}];

// Bloqueo por datos sensibles o prompt injection.
// Se responde 422 SIN llamar al modelo, sin registrar nada
// y sin devolver el contenido ofensivo en el cuerpo de la respuesta.

const e = $input.first().json;
const s = e.seguridad ?? { motivos: [], datos_sensibles: [], injection: { puntaje: 0, umbral: 3, patrones: [] } };

return [{ json: {
  http_status: 422,
  respuesta: {
    status: 'error',
    trace_id: e.trace_id,
    ruta: 'BLOQUEADO_POR_SEGURIDAD',
    accion: 'bloqueado',
    mensaje: 'El mensaje fue bloqueado por el guardrail de seguridad. No se envio al modelo, no se registro nada y el contenido sensible no se propaga en esta respuesta.',
    seguridad: {
      bloqueado: true,
      motivos: s.motivos,
      datos_sensibles: (s.datos_sensibles ?? []).map(function (h) { return { tipo: h.tipo, severidad: h.severidad }; }),
      injection: s.injection
    },
    que_hacer: 'Reenvia el mensaje sin datos personales, credenciales ni instrucciones dirigidas al sistema.'
  }
}}];
